#include "fedspatial/gpu_context.hpp"
#include <algorithm>
#include <cmath>
#include <cstring>
#include <filesystem>
#include <fstream>
#include <iostream>
using namespace fedspatial;
namespace fs=std::filesystem;
static Matrix load(const fs::path&p){std::ifstream f(p);int r,c;if(!(f>>r>>c))throw std::runtime_error("missing fixture "+p.string());Matrix x(r,c);for(double&v:x.a)f>>v;return x;}
static WorkerInput figure_worker(int n){const auto a=load("sync_gpu/tests/fixtures/figure1_reference/worker_0.txt");Matrix s(n,2),z(n,1),x(n,5);for(int i=0;i<n;++i){s(i,0)=a(i,0);s(i,1)=a(i,1);z(i,0)=a(i,2);for(int j=0;j<5;++j)x(i,j)=a(i,j+3);}return{s,z,x};}
static bool medium(){const fs::path f="sync_gpu/tests/fixtures/figure1_reference";auto k=load(f/"knots.txt");GlobalParameters p{load(f/"p_initial_gamma_new.txt"),load(f/"p_initial_global_mu.txt"),load(f/"p_initial_global_sigma.txt"),.25,1.,.11};GpuContext c(0);auto w=figure_worker(100);(void)build_device_mu_sigma_local(c,w,k,p);const auto want=load(f/"p_initial_worker_0_gradient.txt");unsetenv("FEDSPATIAL_THETA_FIRST_TILED");const auto raw0=c.raw_h2d_bytes(),d20=c.result_d2h_bytes();auto scalar=compute_device_delta_theta_theta_first_reduction_streamed(c,w,k,p);const auto active_h2d=c.raw_h2d_bytes()-raw0,active_d2h=c.result_d2h_bytes()-d20;auto b=compute_device_delta_theta_theta_first_reduction_streamed(c,w,k,p);setenv("FEDSPATIAL_THETA_FIRST_TILED","1",1);auto a=compute_device_delta_theta_theta_first_reduction_streamed(c,w,k,p);unsetenv("FEDSPATIAL_THETA_FIRST_TILED");double abs=std::max(std::abs(a.alpha_gradient-want(1,0)),std::abs(a.range_gradient-want(2,0))),scale=std::max({1.,std::abs(want(1,0)),std::abs(want(2,0))}),repeat=std::max({std::abs(scalar.objective-b.objective),std::abs(scalar.alpha_gradient-b.alpha_gradient),std::abs(scalar.range_gradient-b.range_gradient)}),st=std::max({std::abs(scalar.objective-a.objective),std::abs(scalar.alpha_gradient-a.alpha_gradient),std::abs(scalar.range_gradient-a.range_gradient)});const long long diagnostic_d2h=4*sizeof(double);std::cout<<"STREAM_THETA_FIRST_MEDIUM_N=100 PYTHON_AUTOGRAD_MAX_ABS="<<abs<<" MAX_REL="<<abs/scale<<" SCALAR_V_TILED_MAX_ABS="<<st<<" EXACT_REPEAT_ABS="<<repeat<<" ACTIVE_H2D_BYTES="<<active_h2d<<" ACTIVE_D2H_BYTES="<<active_d2h<<" DIAGNOSTIC_D2H_BYTES="<<diagnostic_d2h<<'\n';return abs<=1e-9&&st<=1e-10&&repeat==0.&&active_h2d==0&&active_d2h==diagnostic_d2h;}
static bool small(){Matrix k(2,2),s(3,2),z(3,1),x(3,1),g(1,1),mu(2,1),sig(2,2);double av[]={0,0,1,.2,.3,1.1},kv[]={0,0,1.5,1.5},zv[]={1.2,-.4,.7};std::copy(av,av+6,s.a.begin());std::copy(kv,kv+4,k.a.begin());std::copy(zv,zv+3,z.a.begin());for(double&v:x.a)v=1.;g(0,0)=.15;mu(0,0)=.2;mu(1,0)=-.1;sig(0,0)=.7;sig(1,1)=.4;sig(0,1)=sig(1,0)=.05;Matrix point,want;if(!read_matrix("sync_gpu/tests/fixtures/sync_gpu/DELTA_THETA_POINT0_PARAM.txt",&point)||!read_matrix("sync_gpu/tests/fixtures/sync_gpu/DELTA_THETA_POINT0_GRAD.txt",&want))throw std::runtime_error("missing small autograd fixture");GlobalParameters p{g,mu,sig,point(0,0),point(1,0),point(2,0)};GpuContext c(0);(void)build_device_mu_sigma_local(c,{s,z,x},k,p);const auto raw0=c.raw_h2d_bytes(),d20=c.result_d2h_bytes();auto a=compute_device_delta_theta_theta_first_reduction_streamed(c,{s,z,x},k,p);const auto active_h2d=c.raw_h2d_bytes()-raw0,active_d2h=c.result_d2h_bytes()-d20;auto b=compute_device_delta_theta_theta_first_reduction_streamed(c,{s,z,x},k,p);double abs=std::max(std::abs(a.alpha_gradient-want(1,0)),std::abs(a.range_gradient-want(2,0)));double scale=std::max({1.,std::abs(want(1,0)),std::abs(want(2,0))});double repeat=std::max({std::abs(a.objective-b.objective),std::abs(a.alpha_gradient-b.alpha_gradient),std::abs(a.range_gradient-b.range_gradient)});const long long diagnostic_d2h=4*sizeof(double);std::cout<<"STREAM_THETA_FIRST_SMALL_N=3 GOT_ALPHA="<<a.alpha_gradient<<" WANT_ALPHA="<<want(1,0)<<" GOT_RANGE="<<a.range_gradient<<" WANT_RANGE="<<want(2,0)<<" PYTHON_AUTOGRAD_MAX_ABS="<<abs<<" MAX_REL="<<abs/scale<<" EXACT_REPEAT_ABS="<<repeat<<" ACTIVE_H2D_BYTES="<<active_h2d<<" ACTIVE_D2H_BYTES="<<active_d2h<<" DIAGNOSTIC_D2H_BYTES="<<diagnostic_d2h<<'\n';return abs<=1e-10&&repeat==0.&&active_h2d==0&&active_d2h==diagnostic_d2h;}
int main(){try{const bool ok=small()&&medium();std::cout<<"STREAMED_THETA_FIRST_PYTHON_AUTOGRAD_PARITY="<<(ok?"PASS":"FAIL")<<'\n';return ok?0:1;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 2;}}
